package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
)

type Config struct {
	ConfigDir    string
	DataDir      string
	CacheDir     string
	SelfPath     string
	BashPath     string
	DisableStdin bool
	LoadDotenv   bool
	StrictEnv    bool
	WarnTimeout  time.Duration
	HideEnvDiff  bool
	LogFormat    string
	LogFormatSet bool
	HasConfigFile bool
	LogFilter    *regexp.Regexp
	LogFilterStr string
	WhitelistPrefix []string
	WhitelistExact  map[string]bool
	// raw for status display?
	WhitelistExactList []string
}

func loadConfig(selfPath string) (*Config, error) {
	c := &Config{
		SelfPath:    selfPath,
		BashPath:    "/usr/bin/bash",
		WarnTimeout: 5 * time.Second,
		WhitelistExact: make(map[string]bool),
	}
	// Resolve dirs
	configDir, err := getConfigDir()
	if err != nil {
		return nil, fmt.Errorf("couldn't find a configuration directory for direnv")
	}
	c.ConfigDir = configDir
	dataDir, err := getDataDir()
	if err != nil {
		return nil, fmt.Errorf("couldn't find a data directory for direnv")
	}
	c.DataDir = dataDir
	cacheDir, err := getCacheDir()
	if err != nil {
		return nil, fmt.Errorf("couldn't find a cache directory for direnv")
	}
	c.CacheDir = cacheDir

	// Load toml
	tomlPath := filepath.Join(configDir, "direnv.toml")
	hasFile := false
	if _, err := os.Stat(tomlPath); err == nil {
		hasFile = true
	} else {
		alt := filepath.Join(configDir, "config.toml")
		if _, err2 := os.Stat(alt); err2 == nil {
			tomlPath = alt
			hasFile = true
		}
	}
	c.HasConfigFile = hasFile
	// defaults for log format handling: if no config file, use colored; if has file, use plain unless LogFormat set
	if hasFile {
		var raw struct {
			Global struct {
				BashPath     *string `toml:"bash_path"`
				DisableStdin *bool   `toml:"disable_stdin"`
				LoadDotenv   *bool   `toml:"load_dotenv"`
				StrictEnv    *bool   `toml:"strict_env"`
				WarnTimeout  *string `toml:"warn_timeout"`
				HideEnvDiff  *bool   `toml:"hide_env_diff"`
				LogFormat    *string `toml:"log_format"`
				LogFilter    *string `toml:"log_filter"`
			} `toml:"global"`
			Whitelist struct {
				Prefix []string `toml:"prefix"`
				Exact  []string `toml:"exact"`
			} `toml:"whitelist"`
		}
		// Use BurntSushi to parse, to get identical error messages
		// But WarnTimeout needs custom handling as duration string
		// First try to decode with a struct that has WarnTimeout as string, then parse duration
		// To match error messages for wrong types, we need to let toml decode directly and propagate errors
		// For WarnTimeout, original likely uses a custom type that parses duration and returns time.ParseDuration error
		// We'll decode and then manually handle WarnTimeout parsing to match error format
		_, err := toml.DecodeFile(tomlPath, &raw)
		if err != nil {
			return nil, fmt.Errorf("LoadConfig() failed to parse %s: %v", tomlPath, err)
		}
		if raw.Global.BashPath != nil {
			c.BashPath = *raw.Global.BashPath
		}
		if raw.Global.DisableStdin != nil {
			c.DisableStdin = *raw.Global.DisableStdin
		}
		if raw.Global.LoadDotenv != nil {
			c.LoadDotenv = *raw.Global.LoadDotenv
		}
		if raw.Global.StrictEnv != nil {
			c.StrictEnv = *raw.Global.StrictEnv
		}
		if raw.Global.WarnTimeout != nil {
			d, err := time.ParseDuration(*raw.Global.WarnTimeout)
			if err != nil {
				return nil, fmt.Errorf("LoadConfig() failed to parse %s: toml: line 2 (last key \"global.warn_timeout\"): %v", tomlPath, err)
			}
			c.WarnTimeout = d
		}
		if raw.Global.HideEnvDiff != nil {
			c.HideEnvDiff = *raw.Global.HideEnvDiff
		}
		if raw.Global.LogFormat != nil {
			c.LogFormat = *raw.Global.LogFormat
			c.LogFormatSet = true
		}
		if raw.Global.LogFilter != nil {
			c.LogFilterStr = *raw.Global.LogFilter
			re, err := regexp.Compile(*raw.Global.LogFilter)
			if err != nil {
				// What does original do for invalid regexp? Need to test. For now, treat as error?
				return nil, fmt.Errorf("LoadConfig() failed to parse %s: toml: line 2 (last key \"global.log_filter\"): %v", tomlPath, err)
			}
			c.LogFilter = re
		}
		// Whitelist
		home := os.Getenv("HOME")
		for _, p := range raw.Whitelist.Prefix {
			if strings.HasPrefix(p, "~/") {
				p = filepath.Join(home, strings.TrimPrefix(p, "~/"))
			} else if p == "~" {
				p = home
			}
			c.WhitelistPrefix = append(c.WhitelistPrefix, p)
		}
		for _, e := range raw.Whitelist.Exact {
			if strings.HasPrefix(e, "~/") {
				e = filepath.Join(home, strings.TrimPrefix(e, "~/"))
			} else if e == "~" {
				e = home
			}
			// If e is a dir, it will be treated as dir/.envrc? Actually docs say if directory, append /.envrc
			// But status shows whitelist.exact map[] - need to see how it's stored
			// For now store both the raw and with .envrc appended? Let's store as given and also handle dir case at check time
			c.WhitelistExact[e] = true
			c.WhitelistExactList = append(c.WhitelistExactList, e)
		}
	} else {
		// No config file, defaults already set
	}

	// DIRENV_WARN_TIMEOUT env overrides
	if v := os.Getenv("DIRENV_WARN_TIMEOUT"); v != "" {
		d, err := time.ParseDuration(v)
		if err != nil {
			// Original prints warning 3 times for export? Actually it prints each time loadConfig is called
			// We'll return a special error that caller should log but not fail? Or log here directly?
			// For now, log to stderr and continue with default
			// But need to match: export prints 3 times, status prints once. That suggests loadConfig is called 3 times during export.
			// If we log here, it will print each time loadConfig is called, matching.
			fmt.Fprintf(os.Stderr, "\x1b[31mdirenv: invalid DIRENV_WARN_TIMEOUT: %v\x1b[0m\n", err)
		} else {
			c.WarnTimeout = d
		}
	}

	return c, nil
}

func getConfigDir() (string, error) {
	if v := os.Getenv("DIRENV_CONFIG"); v != "" {
		return v, nil
	}
	if v := os.Getenv("XDG_CONFIG_HOME"); v != "" {
		return filepath.Join(v, "direnv"), nil
	}
	home := os.Getenv("HOME")
	if home == "" {
		return "", fmt.Errorf("no home")
	}
	return filepath.Join(home, ".config", "direnv"), nil
}

func getDataDir() (string, error) {
	if v := os.Getenv("XDG_DATA_HOME"); v != "" {
		return filepath.Join(v, "direnv"), nil
	}
	home := os.Getenv("HOME")
	if home == "" {
		return "", fmt.Errorf("no home")
	}
	return filepath.Join(home, ".local", "share", "direnv"), nil
}

func getCacheDir() (string, error) {
	if v := os.Getenv("XDG_CACHE_HOME"); v != "" {
		return filepath.Join(v, "direnv"), nil
	}
	home := os.Getenv("HOME")
	if home == "" {
		return "", fmt.Errorf("no home")
	}
	return filepath.Join(home, ".cache", "direnv"), nil
}

func (c *Config) AllowDir() string {
	return filepath.Join(c.DataDir, "allow")
}
func (c *Config) DenyDir() string {
	return filepath.Join(c.DataDir, "deny")
}
func (c *Config) RequiredDir() string {
	return filepath.Join(c.DataDir, "required")
}
GOEOF
cat /workspace/config.go
"}

