package main

import (
	"fmt"
	"os"
)

func logStatus(conf *Config, msg string) {
	if conf != nil {
		if conf.LogFormatSet && conf.LogFormat == "-" {
			return
		}
		if conf.LogFilter != nil {
			if !conf.LogFilter.MatchString(msg) {
				return
			}
		}
		if conf.LogFormatSet {
			// Use fmt.Sprintf with log_format, mimicking Go's behavior for missing verbs
			// Original uses fmt.Sprintf(logFormat, msg)? Let's do same
			out := fmt.Sprintf(conf.LogFormat, msg)
			fmt.Fprintln(os.Stderr, out)
			return
		}
		if conf.HasConfigFile {
			fmt.Fprintf(os.Stderr, "direnv: %s\n", msg)
			return
		}
	}
	// Default colored
	fmt.Fprintf(os.Stderr, "\x1b[0mdirenv: %s\n", msg)
}

func logErrorMsg(conf *Config, msg string) {
	// For `log --error` style: "direnv: <msg>" with or without color, not "error" prefix, not filtered by LogFilter? Actually filtered? No, error not filtered.
	// But with LogFormatSet, does it use LogFormat? No, earlier test showed with custom LogFormat, log --error still showed "direnv: hi", not custom. So ignore LogFormat.
	// With "-" ? Does "-" disable error? No, earlier test showed log --error with "-" still showed. So ignore "-".
	if conf != nil && conf.HasConfigFile {
		fmt.Fprintf(os.Stderr, "direnv: %s\n", msg)
		return
	}
	fmt.Fprintf(os.Stderr, "\x1b[31mdirenv: %s\x1b[0m\n", msg)
}

func logError(conf *Config, msg string) {
	// For internal errors: always colored "direnv: error <msg>"
	// conf is ignored for color? Always colored regardless of config.
	fmt.Fprintf(os.Stderr, "\x1b[31mdirenv: error %s\x1b[0m\n", msg)
