	denyHash := sha256.Sum256([]byte(rcPath + "\n"))
	denyHex := hex.EncodeToString(denyHash[:])
	denyPath := filepath.Join(conf.DenyDir(), denyHex)
	if _, err := os.Stat(denyPath); err == nil {
		allowPath := computeAllowPath(conf, rcPath)
		return allowPath, 2
	}
	allowPath := computeAllowPath(conf, rcPath)
	if _, err := os.Stat(allowPath); err == nil {
		return allowPath, 0
	}
	return allowPath, 1
}

func computeAllowPath(conf *Config, rcPath string) string {
	content, err := os.ReadFile(rcPath)
	if err != nil {
		content = []byte{}
	}
	h := sha256.New()
	h.Write([]byte(rcPath + "\n"))
	h.Write(content)
	hexStr := hex.EncodeToString(h.Sum(nil))
	return filepath.Join(conf.AllowDir(), hexStr)
}

func computeDenyPath(conf *Config, rcPath string) string {
	h := sha256.Sum256([]byte(rcPath + "\n"))
	return filepath.Join(conf.DenyDir(), hex.EncodeToString(h[:]))
}

func isWhitelisted(conf *Config, rcPath string) bool {
	for _, prefix := range conf.WhitelistPrefix {
		if strings.HasPrefix(rcPath, prefix) {
			return true
		}
	}
	for e := range conf.WhitelistExact {
		if e == rcPath {
			return true
		}
		if filepath.Join(e, ".envrc") == rcPath || filepath.Join(e, ".env") == rcPath {
			return true
		}
	}
	return false
}

func resolveRCPath(conf *Config, arg string) (string, error) {
	if arg == "" {
		cwd, _ := os.Getwd()
		rc := findRC(conf, cwd)
		if rc == nil {
			return "", fmt.Errorf(".envrc file not found")
		}
		return rc.Path, nil
	}
	abs, err := filepath.Abs(arg)
	if err != nil {
		return "", err
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return "", err
	}
	st, err := os.Lstat(resolved)
	if err != nil {
		return "", err
	}
	if st.IsDir() {
		envrc := filepath.Join(resolved, ".envrc")
		if fileExists(envrc) {
			// Resolve envrc symlink?
			if r2, err := filepath.EvalSymlinks(envrc); err == nil {
				envrc = r2
			}
			return envrc, nil
		}
		if conf.LoadDotenv {
			dotenv := filepath.Join(resolved, ".env")
			if fileExists(dotenv) {
				if r2, err := filepath.EvalSymlinks(dotenv); err == nil {
					dotenv = r2
				}
				return dotenv, nil
			}
		}
		return "", fmt.Errorf(".envrc file not found")
	}
	return resolved, nil
}

func userRelPath(p string) string {
	home := os.Getenv("HOME")
	if home != "" && strings.HasPrefix(p, home+"/") {
		return "~" + strings.TrimPrefix(p, home)
	} else if p == home {
		return "~"
	}
	return p
}
