func formatBash(data map[string]*string) string {
	var parts []string
	for k, v := range data {
		if v == nil {
			parts = append(parts, fmt.Sprintf("unset %s;", k))
		} else {
			parts = append(parts, fmt.Sprintf("export %s=%s;", k, bashEscape(*v)))
		}
	}
	// Random order via map iteration already random? But we collected via range which is random, then parts order is random. Good.
	// However, Go's map iteration randomizes each run, so parts will be random. Good.
	// But to ensure random, we already iterated randomly. No need to shuffle.
	return strings.Join(parts, "")
}

func bashEscape(s string) string {
	if s == "" {
		return "''"
	}
	// Check if unquoted
	if isBashUnquoted(s) {
		return s
	}
	var b strings.Builder
	b.WriteString("$'")
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\'':
			b.WriteString("\\'")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\t':
			b.WriteString("\\t")
		case '\r':
			b.WriteString("\\r")
		default:
			if c < 0x20 || c == 0x7F || c >= 0x80 {
				fmt.Fprintf(&b, "\\x%02x", c)
			} else {
				b.WriteByte(c)
			}
		}
