		c := s[i]
		switch c {
		case ' ':
			b.WriteString("\\ ")
		case '\n':
			b.WriteString("\\n")
		case '\t':
			b.WriteString("\\t")
		case '\r':
			b.WriteString("\\r")
		case '\'':
			b.WriteString("\\'")
		case '\\':
			b.WriteString("\\\\")
		case '"':
			b.WriteString("\"\"\"")
		case '$', '#', '=', '!', '*', '?', '[', ']', '{', '}', '(', ')', '|', '&', '<', '>', ';', '^', '~', '`', '%':
			b.WriteString("\"")
			b.WriteByte(c)
			b.WriteString("\"")
		default:
			if c < 0x20 || c == 0x7F || c >= 0x80 {
				fmt.Fprintf(&b, "\\x%02x", c)
			} else {
				b.WriteByte(c)
			}
		}
	}
	return b.String()
}

func formatVim(data map[string]*string) string {
	var parts []string
	for k, v := range data {
		if v == nil {
			parts = append(parts, fmt.Sprintf("call setenv('%s',v:null)\n", vimEscape(k)))
		} else {
			parts = append(parts, fmt.Sprintf("call setenv('%s','%s')\n", vimEscape(k), vimEscape(*v)))
		}
	}
	return strings.Join(parts, "")
}

func vimEscape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' {
			b.WriteString("''")
		} else if c == '\n' {
			b.WriteString("\\n")
		} else if c == '\r' {
			b.WriteString("\\r")
		} else {
			b.WriteByte(c)
		}
	}
	return b.String()
}

func formatPwsh(data map[string]*string) string {
	var parts []string
	for k, v := range data {
		if v == nil {
			parts = append(parts, fmt.Sprintf("Remove-Item -LiteralPath 'env:/%s';", k))
		} else {
			parts = append(parts, fmt.Sprintf("${env:%s}='%s';", k, strings.ReplaceAll(*v, "'", "''")))
		}
	}
	return strings.Join(parts, "")
}

func formatJSONSingle(data map[string]*string) string {
	m := make(map[string]*string)
	for k, v := range data {
		m[k] = v
	}
	j, _ := json.Marshal(m)
	return string(j) + "\n"
}

func formatJSONPretty(data map[string]*string) string {
	m := make(map[string]*string)
	for k, v := range data {
		m[k] = v
	}
	j, _ := json.MarshalIndent(m, "", "  ")
	return string(j)
}

func formatGHA(data map[string]*string) string {
	var parts []string
	for k, v := range data {
		if v == nil {
			continue
		}
		delim := randomHex(16)
		parts = append(parts, fmt.Sprintf("%s<<ghadelimiter_%s\n%s\nghadelimiter_%s\n", k, delim, *v, delim))
	}
	return strings.Join(parts, "")
}

func randomHex(nbytes int) string {
	b := make([]byte, nbytes)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func formatGzenv(data map[string]*string) string {
	m := make(map[string]*string)
	for k, v := range data {
		m[k] = v
	}
	j, _ := json.Marshal(m)
	enc, _ := compressAndEncode(j)
	return enc
}

func formatSystemd(data map[string]*string) string {
	var parts []string
	for k, v := range data {
		if v == nil {
			continue
		}
		parts = append(parts, fmt.Sprintf("%s=%s\n", k, systemdEscape(*v)))
	}
	return strings.Join(parts, "")
}

func systemdEscape(s string) string {
	needsQuote := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' || c == '\\' || c == '\'' || c == '\n' || c == '\r' || c == ';' {
			needsQuote = true
			break
		}
	}
	if !needsQuote {
		return s
	}
	var b strings.Builder
	b.WriteString("\"")
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' || c == '\\' {
			b.WriteString("\\")
			b.WriteByte(c)
		} else {
			b.WriteByte(c)
		}
	}
	b.WriteString("\"")
	return b.String()
}
